export function route(code: number, retry: boolean, admin: boolean): string {
  if (code === 1) {
    if (retry) {
      if (admin) {
        return 'a';
      }
      return 'b';
    }
    return 'c';
  }
  if (code === 2 && retry) {
    return 'd';
  }
  if (code === 3 || admin) {
    return 'e';
  }
  for (let index = 0; index < code; index += 1) {
    if (index % 2 === 0 && retry) {
      return 'f';
    }
  }
  return 'g';
}
